DROP TABLE IF EXISTS warehouse;

-- DROP SEQUENCE IF EXISTS warehouse_warehouse_id_seq;
-- CREATE SEQUENCE warehouse_warehouse_id_seq;


CREATE TABLE "warehouse" (
  "warehouse_id" int PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, -- SERIAL PRIMARY KEY
  "name" varchar(191) NOT NULL DEFAULT '',
  "country_id" INT NOT NULL DEFAULT 0,
  "region_id" INT NOT NULL DEFAULT 0,
  "city" varchar(191) NOT NULL DEFAULT '',
  "postal_code" varchar(32) NOT NULL DEFAULT '',
  "address_1" varchar(191) NOT NULL DEFAULT '',
  "status" smallint NOT NULL DEFAULT 1,
  "sort_order" INT NOT NULL DEFAULT 0
-- PRIMARY KEY ("warehouse_id")
);
DROP TABLE IF EXISTS product_warehouse;

CREATE TABLE "product_warehouse" (
  "product_id" INT NOT NULL,
  "warehouse_id" INT NOT NULL,
  PRIMARY KEY ("product_id","warehouse_id")
);
